@startuml

class Home {
  + name : string
}

class Department {
  + name : string
}

class Room {
  + roomNumber : string
}

class Bed {
  + bedNumber : string
}

class Category {
  + price : float
}

enum StayType {
  RH
  RNH
  SF
}

class Inhabitant {
  + name : string
  + identificationData : string
}

class Registration {
  + registrationDate : date
}

class Assessment {
  + needsHelp : string
  + suggestedStayType : StayType
}

class WaitingList {
}

class Proposal {
  + date : date
  + status : string
}

class Stay {
  + status : string
  + intakeDate : date
  + discount : float
}

class Invoice {
  + outstandingAmount : float
  + status : string
}

class CreditNote {
  + amount : float
}

class PaymentEvent {
  + amount : float
  + date : date
}

Home "1" *-- "*" Department
Department "1" *-- "*" Room
Room "1" *-- "*" Bed
Bed "*" -- "1" Category
Category "1" -- "1" StayType

Inhabitant "1" -- "*" Stay
Inhabitant "1" -- "1" Registration
Registration "1" -- "1" Assessment
Assessment "1" -- "1" StayType

Stay "1" -- "1" StayType
Stay "1" -- "1" Bed

WaitingList "1" -- "*" Inhabitant
WaitingList "1" -- "1" StayType

Proposal "1" -- "1" Inhabitant
Proposal "1" -- "1" Stay
Proposal "1" -- "1" Bed

Stay "1" -- "*" Invoice
Invoice "1" -- "1" Inhabitant

Invoice "1" -- "0..1" CreditNote
PaymentEvent "1" -- "1" Invoice

@enduml

